(()=>{
const cache=new Map(),colors=['#cf4545','#637da3','#a27e48','#976f8a'];let shapes=[],candidates=[],selected='sp',loading=false,started=false,lastCheck='';
const mode=()=>$('map-mode').value;
const cname=c=>title(c.nmu||c.nm);
function color(n){return colors[Math.max(0,candidates.findIndex(c=>c.n===n))%colors.length];}
function summary(cd){const entry=cache.get(cd);if(!entry)return {label:'—',fill:'#e5e9df',message:'Dados indisponíveis'};const d=entry.d;if(mode()==='counted'){const p=num(d.s.pst);return {label:pct(p),fill:p?`hsl(154 27% ${89-p*.55}%)`:'#e5e9df',message:`${pct(p)} das seções totalizadas`};}const list=candidateList(d),votes=list.reduce((a,c)=>a+num(c.vap),0);if(!votes)return {label:pct(0),fill:'#e5e9df',message:'Aguardando votos apurados'};if(mode()==='leader'&&list.length>1&&num(list[0].vap)===num(list[1].vap))return {label:pct(list[0].pvap),fill:'#dbd8c7',message:'Empate na votação apurada'};const c=mode()==='leader'?list[0]:list.find(c=>c.n===mode());if(!c)return {label:'—',fill:'#e5e9df',message:'Candidatura indisponível'};const p=num(c.pvap),base=color(c.n);return {label:pct(p),fill:`color-mix(in srgb, ${base} ${Math.max(12,Math.min(95,p))}%, #f3f5ef)`,message:`${cname(c)}: ${pct(p)} dos votos válidos`};}
function draw(){const svg=`<svg viewBox="0 0 710 655" role="group" aria-label="${translateText('Percentuais por unidade da federação')}"><g class="map-shapes">${shapes.map(s=>`<path data-map-uf="${s.uf}" d="${s.d}" fill-rule="evenodd"/>`).join('')}</g><g class="map-labels">${shapes.map(s=>`${s.external?`<path class="map-callout" d="M${s.origin.join(',')}L${s.label[0]-19},${s.label[1]}"/>`:''}<g class="map-state-label" data-map-uf="${s.uf}" role="button" tabindex="0"><title></title><text x="${s.label[0]}" y="${s.label[1]-3}" text-anchor="middle" class="map-uf">${s.uf.toUpperCase()}</text><text class="map-value" x="${s.label[0]}" y="${s.label[1]+12}" text-anchor="middle">—</text></g>`).join('')}</g></svg>`;$('map-svg').innerHTML=svg;$('map-svg').querySelectorAll('[data-map-uf]').forEach(el=>{el.onclick=()=>choose(el.dataset.mapUf);if(el.tagName.toLowerCase()==='g')el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(el.dataset.mapUf);}};});paint();}
function choose(cd){selected=cd;paint();}
function paint(){shapes.forEach(s=>{const v=summary(s.uf),name=states.find(a=>a[0]===s.uf)[1],nodes=$('map-svg').querySelectorAll(`[data-map-uf="${s.uf}"]`);nodes.forEach(n=>{n.classList.toggle('map-selected',selected===s.uf);if(n.tagName.toLowerCase()==='path')n.style.fill=v.fill;else{n.setAttribute('aria-label',`${name}: ${translateText(v.message)}`);n.setAttribute('aria-pressed',String(selected===s.uf));n.querySelector('title').textContent=`${name} · ${translateText(v.message)}`;n.querySelector('.map-value').textContent=v.label;}});});$('map-legend').innerHTML=mode()==='counted'?'<span><i style="background:#d4e5da"></i>0% → 100% das seções</span>':candidates.filter(c=>mode()==='leader'||mode()===c.n).map(c=>`<span><i style="background:${color(c.n)}"></i>${safe(cname(c))}</span>`).join('');$('map-legend').innerHTML+='<span><i style="background:#e5e9df"></i>Sem apuração / indisponível</span>';$('map-legend').innerHTML=localizeHTML($('map-legend').innerHTML);detail();table();}
function detail(){const d=cache.get(selected)?.d,name=states.find(s=>s[0]===selected)[1];let html=`<span class="overline">ESTADO SELECIONADO</span><h3><span>${selected.toUpperCase()}</span>${safe(name)}</h3>`;if(!d){html+='<p>Dados desta UF indisponíveis nesta consulta.</p>';}else{const list=candidateList(d),started=num(d.s.st)>0;html+=`<span class="badge">${d.and==='f'?'Totalização encerrada':started?'Apuração em andamento':'Aguardando apuração'}</span><div class="map-detail-votes">${list.map(c=>`<div><div><i style="background:${color(c.n)}"></i><span>${safe(cname(c))}<small>${safe(c.party)} · ${fmt(c.vap)} votos</small></span><b>${pct(c.pvap)}</b></div><div class="map-vote-track"><span style="width:${Math.max(0,Math.min(100,num(c.pvap)))}%;background:${color(c.n)}"></span></div></div>`).join('')}</div>${outcomeHTML(d)}${voteMarginHTML(d)}<div class="map-detail-count"><span>Total de votos apurados<b>${countedVotes(d)===null?'—':fmt(countedVotes(d))}</b></span><p>Válidos, brancos e nulos</p></div><div class="map-detail-count"><span>Seções totalizadas<b>${pct(d.s.pst)}</b></span><p>${fmt(d.s.st)} de ${fmt(d.s.ts)} seções</p></div><p class="map-time">Arquivo TSE<br>${safe(d.dg)} às ${safe(d.hg)} · Brasília</p>`;}html+=`<button id="map-open-state">Consultar ${safe(name)} no painel ↗</button>`;$('map-detail').innerHTML=localizeHTML(html);$('map-open-state').onclick=()=>{setTab('brasil',selected);$('painel').scrollIntoView({behavior:'smooth'});};}
function table(){$('map-thead').innerHTML='<tr><th scope="col">UF</th>'+candidates.map(c=>`<th scope="col">${safe(cname(c))}</th>`).join('')+'<th scope="col">Total de votos apurados</th><th scope="col">Diferença de votos</th><th scope="col">À frente na UF</th><th scope="col">Seções totalizadas</th><th scope="col">Arquivo TSE (Brasília)</th></tr>';$('map-tbody').innerHTML=states.map(([cd,nm])=>{const d=cache.get(cd)?.d,list=d?candidateList(d):[];return `<tr><th scope="row"><button data-table-uf="${cd}">${safe(nm)} · ${cd.toUpperCase()}</button></th>${candidates.map(c=>`<td>${list.find(x=>x.n===c.n)?pct(list.find(x=>x.n===c.n).pvap):'—'}</td>`).join('')}<td>${d&&countedVotes(d)!==null?fmt(countedVotes(d)):'—'}</td><td>${d&&electionResult(d).margin!==null?fmt(electionResult(d).margin):'—'}</td><td>${!d?'Indisponível':!electionResult(d).total?'Sem apuração':electionResult(d).margin===0?'Empate':safe(cname(list[0]))}</td><td>${d?pct(d.s.pst):'—'}</td><td>${d?safe(d.dg+' '+d.hg):'Indisponível'}</td></tr>`;}).join('');$('map-thead').innerHTML=localizeHTML($('map-thead').innerHTML);$('map-tbody').innerHTML=localizeHTML($('map-tbody').innerHTML);$('map-tbody').querySelectorAll('button').forEach(b=>b.onclick=()=>{choose(b.dataset.tableUf);$('map-detail').scrollIntoView({behavior:'smooth',block:'center'});});}
async function load(){if(loading)return;loading=true;started=true;$('map-refresh').disabled=true;cache.clear();paint();let next=0,done=0;async function lane(){while(next<states.length){const cd=states[next++][0];try{const r=await fetch(BASE+`dados/${cd}/${cd}-c0001-e006258-u.json`,{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error();const d=await r.json();validateElectionData(d,{region:cd});cache.set(cd,{d});if(!candidates.length){candidates=candidateList(d).sort((a,b)=>num(a.n)-num(b.n));candidates.forEach(c=>{const option=document.createElement('option');option.value=c.n;option.textContent=translateText(cname(c)+' · % dos votos válidos');$('map-mode').appendChild(option);});}}catch{}done++;$('map-updated').textContent=translateText(`Consultando UFs · ${done}/27`);paint();}}await Promise.all([lane(),lane(),lane()]);loading=false;$('map-refresh').disabled=false;$('map-updated').textContent=translateText(lastCheck=`${cache.size}/27 UFs consultadas às ${new Date().toLocaleTimeString(uiLocale(),{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'})}${cache.size<27?' · Há dados indisponíveis':''}`);}
$('map-mode').onchange=paint;$('map-refresh').onclick=load;
fetch('mapa-uf.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(s=>{shapes=s;draw();const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)&&!started)load();},{rootMargin:'200px'});observer.observe($('mapa'));}).catch(()=>{$('map-svg').textContent=translateText('Não foi possível carregar a malha do mapa.');$('map-updated').textContent=translateText('Mapa indisponível');});
window.addEventListener('languagechange',()=>{paint();for(const option of $('map-mode').options){const c=candidates.find(c=>c.n===option.value);if(c)option.textContent=translateText(cname(c)+' · % dos votos válidos');}$('map-updated').textContent=translateText(lastCheck||'Carregando dados das 27 UFs…');$('map-svg').querySelector('svg')?.setAttribute('aria-label',translateText('Percentuais por unidade da federação'));});
setInterval(()=>{const rect=$('mapa').getBoundingClientRect();if(started&&!document.hidden&&$('auto').checked&&rect.bottom>0&&rect.top<window.innerHeight)load();},60000);
})();


